sys_script_client.script:
function onLoad() {
    'use strict';

    // The terminal status, spelled as the Choice VALUE in
    // ../choices/sys_choice_case_status.xml.
    var TERMINAL_STATUS = 'Closed';

    // Every field the UI Policy protects, in form order. number,
    // opened_date and closed_date are absent on purpose: they are
    // unconditionally read-only in the dictionary, so the platform
    // already renders them server-side as sys_readonly.* controls.
    var FIELDS = [
        'subject',
        'type',
        'status',
        'priority',
        'description',
        'requester_name',
        'requester_email',
        'assigned_group',
        'assigned_agent',
        'pending_reason'
    ];

    // Only a Closed record is locked. On every other status this script
    // returns having changed nothing at all, leaving the form as the
    // dictionary and the field-level ACLs rendered it.
    if (g_form.getValue('status') !== TERMINAL_STATUS) {
        return;
    }

    for (var i = 0; i < FIELDS.length; i++) {
        var field = FIELDS[i];

        // A view may omit a field, and a field-level ACL may remove it
        // from the form entirely. Either way there is nothing to disable
        // and asking the platform to do it would log a client error.
        if (!g_form.hasField(field)) {
            continue;
        }

        // The supported API first. This is what closes the `description`
        // gap: called here it applies, where the equivalent UI Policy
        // action does not.
        g_form.setDisabled(field, true);

        // Then the one case the supported API cannot finish. For a
        // <select> the platform's read-only treatment sets the HTML
        // `readonly` attribute, which the specification defines as having
        // no effect on a select, so the control stays operable. Setting
        // the DOM property is what actually makes it inert. Guarded by
        // tagName so nothing else on the form is touched, and by a
        // null/undefined check because getControl() returns nothing for a
        // field the platform renders without a single addressable
        // control.
        var control = g_form.getControl(field);
        if (control && control.tagName === 'SELECT') {
            control.disabled = true;
        }
    }
}
